column34:
.image-container {
    position: relative;
    text-align: center;
}

.blinking-rectangle {
    position: absolute;
    top: 57%; /* Ajustez ce pourcentage pour positionner correctement */
    left: 41.8%; /* Ajustez ce pourcentage pour positionner correctement */
    width: 5.5%; /* Ajustez la largeur en fonction de votre image */
    height: 8%; /* Ajustez la hauteur en fonction de votre image */
    border: 1px solid red;
    background-color: rgba(255, 0, 0, 0.2);
    animation: blink 1s infinite;
}

@keyframes blink {
    0%, 100% {
        opacity: 1;
    }
    50% {
        opacity: 0;
    }
}

