/* Animation de clignotement */
@keyframes blink {
    0%, 100% {
        opacity: 1;
    }
    50% {
        opacity: 0;
    }
}

/* Zone 1 */
.zone1 {
    top: 66.4%; /* Position verticale pour Zone 1 */
    left: 52%; /* Position horizontale pour Zone 1 */
    width: 6%; /* Largeur de Zone 1 */
    height: 9%; /* Hauteur de Zone 1 */
}

/* Zone 2 */
